enum VoteType { UP, DOWN }
enum Privilege {
    UPVOTE(15), DOWNVOTE(125), COMMENT(50),
    EDIT_OTHERS(2000), CLOSE_VOTE(3000);
    final int requiredRep;
    Privilege(int rep) { this.requiredRep = rep; }
}

class User {
    final String userId, displayName;
    private long reputation = 1; // start with 1

    public User(String id, String name) { this.userId = id; this.displayName = name; }
    public synchronized void addReputation(long delta) {
        reputation = Math.max(1, reputation + delta); // rep floor = 1
    }
    public synchronized long getReputation() { return reputation; }
}

class ReputationService {
    private final Map<String, User> users;
    private static final Map<Privilege, Integer> THRESHOLDS = Map.of(
        Privilege.UPVOTE, 15, Privilege.DOWNVOTE, 125,
        Privilege.COMMENT, 50, Privilege.EDIT_OTHERS, 2000
    );

    public ReputationService(Map<String, User> users) { this.users = users; }

    public void addReputation(String userId, long delta, String reason) {
        User u = users.get(userId);
        if (u != null) u.addReputation(delta);
    }

    public boolean hasPrivilege(String userId, Privilege p) {
        User u = users.get(userId);
        return u != null && u.getReputation() >= THRESHOLDS.getOrDefault(p, 0);
    }

    public void requirePrivilege(String userId, Privilege p) {
        if (!hasPrivilege(userId, p))
            throw new InsufficientReputationException(
                "Need " + THRESHOLDS.get(p) + " rep for " + p);
    }
}

class QnAService {
    private final ConcurrentHashMap<String, Question> questions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Answer> answers = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Vote> votes = new ConcurrentHashMap<>(); // key=userId:postId
    private final ConcurrentHashMap<String, Set<String>> tagIndex = new ConcurrentHashMap<>();
    private final Map<String, User> users = new ConcurrentHashMap<>();
    private final ReputationService repService;

    public QnAService() { this.repService = new ReputationService(users); }

    // ── Ask a question ──
    public String askQuestion(String userId, String title, String body, Set<String> tags) {
        Question q = new Question(userId, title, body, tags);
        questions.put(q.postId, q);
        for (String tag : tags) {
            tagIndex.computeIfAbsent(tag, k -> ConcurrentHashMap.newKeySet()).add(q.postId);
        }
        return q.postId;
    }

    // ── Post an answer ──
    public String postAnswer(String userId, String questionId, String body) {
        Question q = questions.get(questionId);
        if (q == null) throw new PostNotFoundException(questionId);
        Answer a = new Answer(userId, questionId, body);
        answers.put(a.postId, a);
        q.addAnswerId(a.postId);
        return a.postId;
    }

    // ── Vote (the complex one) ──
    public void vote(String userId, String postId, VoteType voteType) {
        // Privilege check
        Privilege needed = (voteType == VoteType.UP) ? Privilege.UPVOTE : Privilege.DOWNVOTE;
        repService.requirePrivilege(userId, needed);

        // Find post (could be question or answer)
        Post post = findPost(postId);
        if (post.authorId.equals(userId))
            throw new SelfVoteException("Cannot vote on own post");

        String voteKey = userId + ":" + postId;
        Vote existing = votes.get(voteKey);

        if (existing != null) {
            if (existing.voteType == voteType) return; // already voted same way → no-op
            // Changing vote — reverse old
            reverseVote(existing, post);
            votes.remove(voteKey);
        }

        // Apply new vote
        Vote newVote = new Vote(UUID.randomUUID().toString(), userId, postId, voteType, Instant.now());
        votes.put(voteKey, newVote);
        applyVote(newVote, post);
    }

    private void applyVote(Vote vote, Post post) {
        boolean isQuestion = (post instanceof Question);
        if (vote.voteType == VoteType.UP) {
            post.updateVoteScore(1);
            repService.addReputation(post.authorId, isQuestion ? 5 : 10, "upvote");
        } else {
            post.updateVoteScore(-1);
            repService.addReputation(post.authorId, -2, "downvote");
            repService.addReputation(vote.userId, -1, "downvote_cost"); // costs the voter
        }
    }

    private void reverseVote(Vote vote, Post post) {
        boolean isQuestion = (post instanceof Question);
        if (vote.voteType == VoteType.UP) {
            post.updateVoteScore(-1);
            repService.addReputation(post.authorId, isQuestion ? -5 : -10, "upvote_reversed");
        } else {
            post.updateVoteScore(1);
            repService.addReputation(post.authorId, 2, "downvote_reversed");
            repService.addReputation(vote.userId, 1, "downvote_cost_reversed");
        }
    }

    // ── Accept answer ──
    public void acceptAnswer(String userId, String answerId) {
        Answer answer = answers.get(answerId);
        if (answer == null) throw new PostNotFoundException(answerId);
        Question question = questions.get(answer.questionId);
        if (question == null) throw new PostNotFoundException(answer.questionId);
        if (!question.authorId.equals(userId))
            throw new NotQuestionAuthorException("Only the asker can accept");

        // Un-accept previous if exists
        if (question.acceptedAnswerId != null) {
            Answer old = answers.get(question.acceptedAnswerId);
            if (old != null) {
                old.unmarkAccepted();
                repService.addReputation(old.authorId, -15, "unaccepted");
                repService.addReputation(userId, -2, "unaccepted_asker");
            }
        }

        // Accept new
        answer.markAccepted();
        question.acceptAnswer(answerId);
        repService.addReputation(answer.authorId, 15, "accepted_answer");
        repService.addReputation(userId, 2, "accepted_asker_bonus");
    }

    // ── Comment ──
    public void addComment(String userId, String postId, String body) {
        repService.requirePrivilege(userId, Privilege.COMMENT);
        Post post = findPost(postId);
        post.addComment(new Comment(UUID.randomUUID().toString(), userId, body, Instant.now()));
    }

    // ── Query ──
    public List<Question> getQuestionsByTag(String tag) {
        Set<String> ids = tagIndex.getOrDefault(tag, Set.of());
        return ids.stream().map(questions::get).filter(Objects::nonNull)
            .sorted(Comparator.comparingInt((Question q) -> q.voteScore.get()).reversed())
            .toList();
    }

    private Post findPost(String postId) {
        Post p = questions.get(postId);
        if (p == null) p = answers.get(postId);
        if (p == null) throw new PostNotFoundException(postId);
        return p;
    }
}
